text:
.landing .pricing-section :is(button, a):focus-visible {
  outline: 2px solid var(--pricing-accent);
  outline-offset: 2px;
}
.pricing-section,
.pricing-section *,
.landing .pricing-section :is(.pricing-card, .pricing-button) {
  transition:
    background-color 250ms,
    color 250ms,
    border-color 250ms,
    translate 220ms ease,
    filter 180ms ease,
    box-shadow 200ms ease;
}
@media (hover: hover) and (pointer: fine) {
  .pricing-section .pricing-button:hover:not(:disabled) {
    box-shadow: 0 6px 24px
      color-mix(in srgb, var(--landing-violet) 24%, transparent);
  }
  .pricing-section .pricing-outline:hover:not(:disabled) {
    border-color: var(--pricing-accent);
  }
}
@media (prefers-reduced-motion: reduce) {
  .pricing-section,
  .pricing-section *,
  .pricing-section *::before,
  .pricing-section *::after,
  .landing .pricing-section :is(.pricing-card, .pricing-button) {
    transition: none;
    animation: none;
  }
}
